const fs = require('fs');
const p = 'src/widgets/VizWidget/VizWidget.tsx';
let s = fs.readFileSync(p, 'utf8');
s = s.replace("import {Suspense, useCallback, useMemo, useState} from 'react';", "import {useCallback, useMemo, useState} from 'react';");
s = s.replace("import type {RenderErrorOpts} from '@gravity-ui/chartkit';", "import type {ChartKitProps} from '@gravity-ui/chartkit';");
