s = s.replace("function renderChartError({message, resetError}: RenderErrorOpts) {", "function renderChartError({message, resetError}: RenderErrorArgs) {");
s = s.replace(`    return (
        <Suspense fallback={<ChartSkeleton />}>
            <EngineChart spec={spec} />
        </Suspense>
    );`, `    return <EngineChart spec={spec} />;`);
fs.writeFileSync(p, s);
EOF
